//! The hand-maintained IDL cannot drift from the program.
//!
//! SPEL has no release for LEZ v0.3, so `idl/lez_registry.idl.json` is written
//! by hand in SPEL's IDL format rather than generated by SPEL's macro. Hand
//! maintenance is only acceptable with a check that fails the moment the two
//! disagree, and this is that check:
//!
//! 1. The file is parsed with **SPEL's own IDL types** (`spel-framework-core`'s
//!    `idl.rs`, vendored), so a file SPEL tooling could not read fails here.
//! 2. The instruction list is compared with [`Instruction::NAMES`], in order,
//!    because borsh writes the variant index on the wire.
//! 3. For every instruction a sample value with a distinct sentinel in every
//!    field is borsh-encoded by the real enum, then **decoded using only the
//!    IDL** (field names, order and types). The decode must consume every
//!    byte and recover each sentinel under the right name. A reordered, added,
//!    removed or retyped field fails.
//! 4. The account list of every instruction is compared with what the SDK's
//!    builders put on the wire: names, order, signer and writable flags.
//! 5. The account types (`Entry`, `GlobalState`, `DirectorySlot`) get the same
//!    decode-and-compare treatment as the instructions.

#[allow(dead_code)]
#[path = "../../vendor/spel/spel-framework-core/src/idl.rs"]
mod spel_idl;

use lez_registry_core::{self as core_, instruction::*};
use lez_registry_sdk as sdk;
use serde_json::{json, Value};
use spel_idl::{IdlType, SpelIdl};
use std::collections::HashMap;

const IDL: &str = include_str!("../../idl/lez_registry.idl.json");

fn idl() -> SpelIdl {
    serde_json::from_str(IDL).expect("the IDL parses with SPEL's own IDL types")
}

/// Decode borsh bytes into JSON, driven only by the IDL.
struct Decoder<'a> {
    types: HashMap<String, &'a spel_idl::IdlTypeDef>,
    bytes: &'a [u8],
    pos: usize,
}

impl<'a> Decoder<'a> {
    fn take(&mut self, n: usize) -> &'a [u8] {
        assert!(self.pos + n <= self.bytes.len(), "the IDL describes more bytes than the enum wrote");
        let s = &self.bytes[self.pos..self.pos + n];
        self.pos += n;
        s
    }

    fn u32(&mut self) -> u32 {
        u32::from_le_bytes(self.take(4).try_into().unwrap())
    }

    fn value(&mut self, t: &IdlType) -> Value {
        match t {
            IdlType::Primitive(p) => match p.as_str() {
                "u8" => json!(self.take(1)[0]),
                "bool" => {
                    let b = self.take(1)[0];
                    assert!(b <= 1, "bool byte {b}");
                    json!(b == 1)
                }
                "u32" => json!(self.u32()),
                "u64" => json!(u64::from_le_bytes(self.take(8).try_into().unwrap())),
                "string" => {
                    let n = self.u32() as usize;
                    json!(String::from_utf8(self.take(n).to_vec()).expect("utf-8"))
                }
                other => panic!("primitive {other} not used by this IDL"),
            },
            IdlType::Vec { vec } => {
                let n = self.u32();
                Value::Array((0..n).map(|_| self.value(vec)).collect())
            }
            IdlType::Option { option } => match self.take(1)[0] {
                0 => Value::Null,
                1 => self.value(option),
                b => panic!("option tag {b}"),
            },
            IdlType::Array { array } => {
                let (inner, n) = (&array.0, array.1);
                assert!(matches!(inner.as_ref(), IdlType::Primitive(p) if p == "u8"));
                json!(sdk::hex(self.take(n)))
            }
            IdlType::Defined { defined } => {
                let def = *self.types.get(defined).unwrap_or_else(|| panic!("type {defined} is not in the IDL"));
                self.typedef(def)
            }
        }
    }

    fn typedef(&mut self, def: &spel_idl::IdlTypeDef) -> Value {
        match def.kind.as_str() {
            "struct" => {
                let mut m = serde_json::Map::new();
                for f in &def.fields {
                    m.insert(f.name.clone(), self.value(&f.type_));
                }
                Value::Object(m)
            }
            "enum" => {
                let i = self.take(1)[0] as usize;
                let v = def.variants.get(i).unwrap_or_else(|| panic!("variant {i} is not in the IDL"));
                assert!(v.fields.is_empty());
                json!(v.name)
            }
            k => panic!("kind {k}"),
        }
    }
}

fn decoder<'a>(idl: &'a SpelIdl, bytes: &'a [u8]) -> Decoder<'a> {
    let mut types: HashMap<String, &spel_idl::IdlTypeDef> =
        idl.types.iter().map(|t| (t.name.clone(), t)).collect();
    for a in &idl.accounts {
        types.insert(a.name.clone(), &a.type_);
    }
    Decoder { types, bytes, pos: 0 }
}

/// Decode an instruction's bytes with the IDL: variant index, then args.
fn decode_instruction(idl: &SpelIdl, bytes: &[u8]) -> (String, Value) {
    let mut d = decoder(idl, bytes);
    let index = d.take(1)[0] as usize;
    let ix = &idl.instructions[index];
    let mut m = serde_json::Map::new();
    for a in &ix.args {
        m.insert(a.name.clone(), d.value(&a.type_));
    }
    assert_eq!(d.pos, bytes.len(), "{}: the IDL leaves bytes unread", ix.name);
    (ix.name.clone(), Value::Object(m))
}

const PROGRAM: [u8; 32] = [0x11; 32];
const AUTHOR: [u8; 32] = [0x22; 32];
const IMAGE: [u8; 32] = [0x33; 32];
const REBUILT: [u8; 32] = [0x44; 32];

fn key() -> EntryKey {
    EntryKey { program: PROGRAM, publisher: Some(AUTHOR) }
}
fn key_json() -> Value {
    json!({ "program": sdk::hex(&PROGRAM), "publisher": sdk::hex(&AUTHOR) })
}
fn header() -> HeaderView {
    HeaderView { image_id: IMAGE, immutable: true }
}
fn header_json() -> Value {
    json!({ "image_id": sdk::hex(&IMAGE), "immutable": true })
}
const AT: core_::Stamp = core_::Stamp { block: 7, millis: 9 };
fn at_json() -> Value {
    json!({ "block": 7, "millis": 9 })
}
fn claim() -> core_::SourceClaim {
    core_::SourceClaim {
        repository: "REPO".into(),
        commit: [0x55; 20],
        source_digest: [0x66; 32],
        build: core_::BuildEnvironment { image_digest: [0x77; 32], toolchain: "TC".into(), network_disabled: true },
    }
}
fn claim_json() -> Value {
    json!({
        "repository": "REPO", "commit": sdk::hex(&[0x55; 20]), "source_digest": sdk::hex(&[0x66; 32]),
        "build": { "image_digest": sdk::hex(&[0x77; 32]), "toolchain": "TC", "network_disabled": true }
    })
}

/// One sample per variant, with what the IDL-driven decode must recover.
fn samples() -> Vec<(Instruction, Value)> {
    vec![
        (Instruction::Initialize, json!({})),
        (
            Instruction::Register {
                key: key(),
                header: header(),
                seq_index: 5,
                at: AT,
                name: "NAME".into(),
                version: "VER".into(),
                description: "DESC".into(),
                tags: vec!["T1".into(), "T2".into()],
                idl: "IDL".into(),
                source: Some(claim()),
            },
            json!({
                "key": key_json(), "header": header_json(), "seq_index": 5, "at": at_json(),
                "name": "NAME", "version": "VER", "description": "DESC", "tags": ["T1", "T2"],
                "idl": "IDL", "source": claim_json()
            }),
        ),
        (
            Instruction::Update { key: key(), version: "VER".into(), description: "DESC".into(), idl: "IDL".into() },
            json!({ "key": key_json(), "version": "VER", "description": "DESC", "idl": "IDL" }),
        ),
        (
            Instruction::ClaimSource { key: key(), claim: claim() },
            json!({ "key": key_json(), "claim": claim_json() }),
        ),
        (
            Instruction::RecordRebuild { key: key(), header: header(), rebuilt: REBUILT, at: AT },
            json!({ "key": key_json(), "header": header_json(), "rebuilt": sdk::hex(&REBUILT), "at": at_json() }),
        ),
        (
            Instruction::SyncHeader { key: key(), header: header() },
            json!({ "key": key_json(), "header": header_json() }),
        ),
        (Instruction::Freeze { key: key() }, json!({ "key": key_json() })),
    ]
}

#[test]
fn the_idl_is_in_spels_format_and_names_the_instruction_enum() {
    let idl = idl();
    assert_eq!(idl.name, "lez_registry");
    assert_eq!(
        idl.instruction_type.as_deref(),
        Some("lez_registry_core::instruction::Instruction")
    );
    let names: Vec<&str> = idl.instructions.iter().map(|i| i.name.as_str()).collect();
    assert_eq!(names, Instruction::NAMES, "instruction order is the borsh variant index");
}

#[test]
fn every_instruction_decodes_from_the_idl_alone() {
    let idl = idl();
    let all = samples();
    assert_eq!(all.len(), Instruction::NAMES.len(), "a sample for every variant");
    for (ix, expected) in all {
        let bytes = borsh::to_vec(&ix).unwrap();
        let (name, got) = decode_instruction(&idl, &bytes);
        assert_eq!(name, Instruction::NAMES[ix.index() as usize]);
        assert_eq!(got, expected, "{name}: the IDL's args are not the enum's fields");
        // And the variant names the IDL gives agree with the enum's.
        let v = idl.instructions[ix.index() as usize].variant.clone().unwrap();
        assert!(format!("{ix:?}").starts_with(&v), "{name}: variant {v}");
    }
}

#[test]
fn every_instructions_accounts_are_what_the_sdk_puts_on_the_wire() {
    let idl = idl();
    let reg = [0x99; 32];
    let tags: Vec<String> = vec![];
    let register = sdk::build_register(
        &reg,
        &sdk::RegisterRequest {
            program: &PROGRAM,
            author: &AUTHOR,
            deployer: false,
            header: header(),
            seq_index: 0,
            at: AT,
            name: "n",
            version: "v",
            description: "",
            tags: &tags,
            idl: "",
            source: None,
        },
    )
    .unwrap();
    let txs = vec![
        sdk::build_initialize(&reg),
        register,
        sdk::build_update(&reg, &key(), &AUTHOR, "v", "", "").unwrap(),
        sdk::build_claim_source(&reg, &key(), &AUTHOR, claim()).unwrap(),
        sdk::build_record_rebuild(&reg, &key(), header(), REBUILT, AT, &AUTHOR),
        sdk::build_sync_header(&reg, &key(), header()),
        sdk::build_freeze(&reg, &key(), &AUTHOR),
    ];
    for tx in txs {
        let ix = &idl.instructions[tx.instruction_index as usize];
        assert_eq!(ix.name, tx.instruction);
        let got: Vec<(String, bool, bool)> = tx
            .accounts
            .iter()
            .map(|a| (a.role.as_str().to_string(), a.signer, a.writable))
            .collect();
        let want: Vec<(String, bool, bool)> =
            ix.accounts.iter().map(|a| (a.name.clone(), a.signer, a.writable)).collect();
        assert_eq!(got, want, "{}: accounts", ix.name);
        for (a, item) in tx.accounts.iter().zip(&ix.accounts) {
            // `owner` in the IDL names whose shard the input selects; absent
            // means the registry's own.
            let owner = item.owner.as_deref().map(|o| sdk::parse_account(o).unwrap()).unwrap_or(reg);
            assert_eq!(a.selector.program, owner, "{}.{}: shard owner", ix.name, item.name);
        }
    }
}

#[test]
fn the_account_types_decode_from_the_idl_alone() {
    let idl = idl();
    let mut e = core_::Entry::new(PROGRAM, AT, "NAME".into(), "VER".into(), AUTHOR, core_::Publisher::ThirdParty)
        .unwrap()
        .with_header(IMAGE, true);
    e.description = "DESC".into();
    e.tags = vec!["T".into()];
    e.idl = Some([1u8; 38]);
    e.verification = core_::Verification::claim(claim()).unwrap();
    e.verification.record_rebuild(IMAGE, IMAGE, [0x88; 32], AT).unwrap();
    let bytes = borsh::to_vec(&e).unwrap();
    let def = &idl.accounts.iter().find(|a| a.name == "Entry").unwrap().type_;
    let mut d = decoder(&idl, &bytes);
    let got = d.typedef(def);
    assert_eq!(d.pos, bytes.len(), "Entry: the IDL leaves bytes unread");
    assert_eq!(
        got,
        json!({
            "program_id": sdk::hex(&PROGRAM), "image_id": sdk::hex(&IMAGE), "header_immutable": true,
            "registered_at": at_json(), "name": "NAME", "version": "VER", "author": sdk::hex(&AUTHOR),
            "publisher": "ThirdParty", "description": "DESC", "tags": ["T"], "idl": sdk::hex(&[1u8; 38]),
            "verification": { "state": "Verified", "claim": claim_json(), "last_checked": at_json(),
                              "attester": sdk::hex(&[0x88; 32]) },
            "frozen": false
        })
    );

    for (name, bytes) in [
        ("GlobalState", borsh::to_vec(&core_::GlobalState { total_entries: 3 }).unwrap()),
        (
            "DirectorySlot",
            borsh::to_vec(&core_::DirectorySlot { program_id: PROGRAM, entry_seed: IMAGE }).unwrap(),
        ),
    ] {
        let def = &idl.accounts.iter().find(|a| a.name == name).unwrap().type_;
        let mut d = decoder(&idl, &bytes);
        let _ = d.typedef(def);
        assert_eq!(d.pos, bytes.len(), "{name}: size");
    }

    // Every verification state the core can reach has a name in the IDL, in order.
    let states = &idl.types.iter().find(|t| t.name == "VerificationState").unwrap().variants;
    for (i, s) in [
        core_::VerificationState::Unclaimed,
        core_::VerificationState::Claimed,
        core_::VerificationState::Verified,
        core_::VerificationState::Unreproducible,
        core_::VerificationState::Mismatched,
        core_::VerificationState::Stale,
    ]
    .iter()
    .enumerate()
    {
        assert_eq!(borsh::to_vec(s).unwrap(), vec![i as u8]);
        assert_eq!(format!("{s:?}"), states[i].name);
    }
    assert_eq!(states.len(), 6);
}

#[test]
fn the_errors_the_guest_raises_are_the_errors_the_idl_lists() {
    let guest = include_str!("../../program/src/bin/lez_registry.rs");
    let idl = idl();
    for e in &idl.errors {
        assert!(
            guest.contains(&format!("\"E{}\"", e.code)),
            "IDL error {} ({}) is never raised by the guest",
            e.code,
            e.name
        );
    }
    let raised = guest.matches("= \"E9").count();
    assert_eq!(raised, idl.errors.len(), "the guest defines codes the IDL does not list");
}
